<section class="page-heading">
    <div><div class="eyebrow">Reference data</div><h1>Markets</h1><p>Maintain the active trading locations where MPIDS collects and publishes prices.</p></div>
    <div class="heading-actions"><button class="button button-primary" type="button" data-open-modal="market-modal"><i class="fa-solid fa-plus"></i><span>Add market</span></button></div>
</section>
<section class="panel"><div class="table-wrap"><table class="data-table"><caption class="visually-hidden">Markets where MPIDS collects and publishes prices</caption><thead><tr><th scope="col">Market</th><th scope="col">County</th><th scope="col">Sub-county</th><th scope="col">Status</th><th scope="col">Actions</th></tr></thead><tbody id="markets-table"><tr><td colspan="5" class="table-loading"><i class="fa-solid fa-circle-notch fa-spin"></i><span>Loading markets</span></td></tr></tbody></table></div></section>
<div class="modal" id="market-modal" role="dialog" aria-modal="true" aria-labelledby="market-title"><div class="modal-dialog"><div class="modal-header"><h2 id="market-title">Add market</h2><button class="icon-button" type="button" data-modal-close aria-label="Close"><i class="fa-solid fa-xmark"></i></button></div><form id="market-form"><div class="modal-body"><div class="form-grid"><div class="form-field"><label for="market-name">Market name <span>*</span></label><input id="market-name" name="name" required><span class="field-error" data-error-for="name"></span></div><div class="form-field"><label for="market-county">County <span>*</span></label><input id="market-county" name="county" required><span class="field-error" data-error-for="county"></span></div><div class="form-field"><label for="market-sub-county">Sub-county</label><input id="market-sub-county" name="sub_county"><span class="field-error" data-error-for="sub_county"></span></div><div class="form-field"><label for="market-active">Availability</label><select id="market-active" name="is_active"><option value="1">Active</option><option value="0">Inactive</option></select></div></div></div><div class="modal-footer"><button class="button button-secondary" type="button" data-modal-close>Cancel</button><button class="button button-primary" type="submit"><i class="fa-solid fa-check"></i><span>Save market</span></button></div></form></div></div>
